import sqlalchemy as sa

# Define a version number for the database generated by these writers
# Increment this version number any time a change is made to the schema of the
# assets database
# NOTE: When upgrading this, remember to add a downgrade in:
# .ingestion_db_migrations
INGESTION_DB_VERSION = 0


metadata = sa.MetaData()

markets = sa.Table(
    'markets',
    sa.Column(
        'market',
        sa.Text,
        unique=True,
        nullable=False,
        primary_key=True),
)

countries = sa.Table(
    sa.Column('country_code', sa.Text, nullable=False, primary_key=True),
    sa.Column('currency', sa.Text, nullable=False)
)

# calendars are mapped to operating_mic
calendars = sa.Table(
    'calendars',
    metadata,
    sa.Column('calendar', sa.Text, unique=True, nullable=True, primary_key=True)
)

operating_mics = sa.Table(
    'operating_mics',
    sa.Column('operating_mic', sa.Text, unique=True, nullable=False, primary_key=True),
    sa.Column('calendar', sa.Text, sa.ForeignKey(calendars.c.calendar)),
    sa.Column('country_code', sa.Text, sa.ForeignKey(countries.c.country_code)),
    sa.Column('market', sa.Text, sa.ForeignKey(markets.c.market))
)

exchanges = sa.Table(
    'exchanges',
    metadata,
    sa.Column('mic', sa.Text, nullable=False, unique=True, primary_key=True),
    sa.Column('exchange_name', sa.Text, unique=True, nullable=False),
    sa.Column('operating_mic', sa.Text, sa.ForeignKey(operating_mics.c.mic))
)

asset_types = sa.Table(
    'asset_types',
    sa.Column('asset_type', sa.Text, unique=True, nullable=False, primary_key=True),
    sa.Column('market', sa.Text, sa.ForeignKey(markets.c.market)),
    sa.Column('description', sa.Text))

equity_assets = sa.Table(
    'equity_assets',
    metadata,
    sa.Column('sid', sa.Integer, unique=True, nullable=False, primary_key=True),
    sa.Column('symbol', sa.Text, unique=True, nullable=False),
    sa.Column('equity_name', sa.Text),
    sa.Column('asset_type', sa.Text, sa.ForeignKey(asset_types.c.asset_type)),
    sa.Column('exchange', sa.Text, sa.ForeignKey(exchanges.c.mic)))

splits = sa.Table(
    'splits',
    metadata,
    sa.Column('sid', sa.Integer, sa.ForeignKey(equity_assets.c.sid)),
    sa.Column('first_timestamp', sa.Integer, default=-1),
    sa.Column('last_timestamp', sa.Integer, default=-1))

dividends = sa.Table(
    'dividends',
    metadata,
    sa.Column('sid', sa.Integer, sa.ForeignKey(equity_assets.c.sid)),
    sa.Column('first_timestamp', sa.Integer, default=-1),
    sa.Column('last_timestamp', sa.Integer, default=-1))

bars = sa.Table(
    'bars',
    metadata,
    sa.Column('sid', sa.Integer, sa.ForeignKey(equity_assets.c.sid)),
    sa.Column('first_timestamp', sa.Integer, default=-1),
    sa.Column('last_timestamp', sa.Integer, default=-1))

# this is used for tracking symbol changes
equity_asset_symbols = sa.Table(
    'equity_asset_symbols',
    sa.Column('sid', sa.Integer, sa.ForeignKey(equity_assets.c.sid)),
    sa.Column('symbol', sa.Text, nullable=False),
    sa.Column('as_of', sa.Integer, nullable=False))

exchange_asset_types = sa.Table(
    'exchange_asset_types',
    sa.Column('asset_type', sa.Text, sa.ForeignKey(asset_types.c.asset_type)),
    sa.Column('exchange', sa.Text, sa.ForeignKey(exchanges.c.exchange_name)))

